"""Streamlit dashboard for the NOWA x Warriner validation demo."""

from __future__ import annotations

from dataclasses import asdict
from pathlib import Path
import sys
from typing import Any

if __package__ in (None, ""):
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from nowa_validation.nowa_colony import NOWAColony
from nowa_validation.warriner_validator import ValidationResult, WarrinerValidator
from nowa_validation.word_stimulus_encoder import WordStimulusEncoder


DISCLAIMER = (
    "This report was generated by a computational simulation (NOWA synthetic "
    "respondent platform). It does NOT involve real human respondents. Findings "
    "are directional and intended to support hypothesis generation, creative "
    "triage, and pre-research exploration. They should NOT be used as the sole "
    "basis for high-stakes marketing decisions or substituted for human "
    "consumer research."
)


def _result_table(result: ValidationResult) -> list[dict[str, Any]]:
    rows = []
    for word, human_v, nowa_v, human_a, nowa_a in zip(
        result.words,
        result.warriner_valence_norm,
        result.nowa_valence_shifts,
        result.warriner_arousal_norm,
        result.nowa_arousal_shifts,
    ):
        rows.append(
            {
                "word": word,
                "warriner_valence": human_v,
                "nowa_valence_shift": nowa_v,
                "valence_residual": nowa_v - human_v,
                "warriner_arousal": human_a,
                "nowa_arousal_shift": nowa_a,
            }
        )
    return rows


def main() -> None:
    try:
        import streamlit as st
    except Exception as exc:
        raise SystemExit("streamlit is not installed. Install requirements.txt to run the UI.") from exc

    st.set_page_config(page_title="NOWA x Warriner Validation", layout="wide")
    st.title("NOWA x Warriner Validation")

    with st.sidebar:
        st.header("Configuration")
        default_csv = Path(__file__).resolve().parents[2] / "data" / "Ratings_Warriner_et_al.csv"
        csv_path = st.text_input("Warriner CSV path", str(default_csv))
        encoder_mode = st.selectbox(
            "Encoder mode",
            ["lexical", "sbert_neighbors", "direct_vad"],
            index=1,
            key="encoder_mode_v2",
            help=(
                "Use sbert_neighbors for held-out validation. Lexical only works as an "
                "in-vocabulary smoke test because held-out words are not in memory."
            ),
        )
        protocol = st.selectbox(
            "Validation protocol",
            ["heldout", "in_vocab"],
            key="validation_protocol_v1",
            help=(
                "heldout keeps seed and test words disjoint. in_vocab is a smoke test "
                "that confirms the core colony responds to words already seeded in hippocampus."
            ),
        )
        n_agents = st.slider("Colony size", 50, 500, 100, 10)
        n_words = st.slider("Words to test", 50, 1000, 300, 50)
        ticks = st.slider("Ticks per stimulus", 5, 30, 20, 1)
        seed_size = st.slider("Seed size", 100, 2000, 500, 100)
        st.subheader("Signal parameters")
        affective_gain = st.slider(
            "Affective gain",
            0.5,
            3.0,
            1.8,
            0.1,
            help="Multiplier for memory VAD to AffectiveSpace mapping.",
        )
        signal_ticks = st.slider(
            "Signal ticks",
            1,
            10,
            3,
            1,
            help="How many ticks the stimulus is actively injected.",
        )
        memory_top_k = st.slider(
            "Memory TOP-K",
            1,
            10,
            3,
            1,
            help="Top-K activated episodes for the VAD signal.",
        )
        memory_min_activation = st.slider(
            "Min activation threshold",
            0.0,
            1.0,
            0.3,
            0.05,
            help="Minimum activation_energy for episode inclusion.",
        )
        seed = st.number_input("Random seed", min_value=0, value=42, step=1)
        run_clicked = st.button("Run Validation", type="primary")

    if not run_clicked:
        st.info("Configure the validation run in the sidebar and start it when ready.")
        st.caption(DISCLAIMER)
        return

    if encoder_mode == "lexical" and protocol == "heldout":
        st.warning(
            "Lexical + heldout is expected to produce near-zero activation: the test words "
            "are deliberately absent from hippocampal seed memory. Use sbert_neighbors for "
            "held-out generalization or in_vocab for a core smoke test."
        )
    if encoder_mode == "direct_vad":
        st.warning("direct_vad is a diagnostic oracle baseline, not a final validation result.")
    if protocol == "in_vocab":
        st.warning("in_vocab is a smoke test where test words are already seeded, not held-out validation.")

    progress = st.progress(0.0)
    status = st.empty()

    def on_progress(index: int, total: int, word: str) -> None:
        progress.progress(index / max(1, total))
        status.write(f"Processing {index}/{total}: {word}")

    colony = NOWAColony(
        n_agents=n_agents,
        ticks_per_stimulus=ticks,
        signal_ticks=signal_ticks,
        affective_gain=affective_gain,
        memory_top_k=memory_top_k,
        memory_min_activation=memory_min_activation,
        seed=int(seed),
    )
    encoder = WordStimulusEncoder(mode=encoder_mode)
    validator = WarrinerValidator(
        warriner_csv_path=csv_path,
        colony=colony,
        encoder=encoder,
        n_words=n_words,
        validation_protocol=protocol,
        seed=int(seed),
    )
    result = validator.run(seed_size=seed_size, progress_callback=on_progress)
    diagnostics = validator.diagnose_zero_activations(result)

    tabs = st.tabs(
        [
            "Main Results",
            "Scatter Plot",
            "Per-Archetype",
            "Memory Diagnostics",
            "Word-Level Data",
            "Neuromodulators",
        ]
    )

    with tabs[0]:
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("Spearman rho(V)", f"{result.spearman_rho_valence:.3f}")
        c2.metric("Pearson r(V)", f"{result.pearson_r_valence:.3f}")
        c3.metric("CCC(V)", f"{result.ccc_valence:.3f}")
        c4.metric("Spearman rho(A)", f"{result.spearman_rho_arousal:.3f}")
        st.write(result.summary())
        st.write(f"Core backend: `{colony.backend_name}`")
        st.write(f"Validation protocol: `{protocol}`")
        st.metric("SD ratio", f"{result.sd_ratio:.3f}")
        st.metric("Mean activated memories", f"{result.mean_activated_memories:.2f}")

    with tabs[1]:
        rows = _result_table(result)
        try:
            import plotly.express as px

            fig = px.scatter(
                rows,
                x="warriner_valence",
                y="nowa_valence_shift",
                hover_name="word",
                trendline="ols",
            )
            st.plotly_chart(fig, use_container_width=True)
        except Exception:
            st.dataframe(rows, use_container_width=True)

    with tabs[2]:
        st.bar_chart(result.archetype_correlations)
        st.json(result.archetype_n_agents)

    with tabs[3]:
        st.metric("Zero activation ratio", f"{result.zero_activation_ratio:.2%}")
        st.write(diagnostics["recommendation"])
        st.write(diagnostics["worst_words"])

    with tabs[4]:
        rows = _result_table(result)
        st.dataframe(rows, use_container_width=True)
        st.download_button(
            "Download JSON",
            data=str(asdict(result)),
            file_name="nowa_warriner_validation.json",
        )

    with tabs[5]:
        st.metric("Spearman rho(DA, V)", f"{result.spearman_rho_da_valence:.3f}")
        st.metric("Spearman rho(Cortisol, V)", f"{result.spearman_rho_cortisol_valence:.3f}")
        nm_rows = [
            {
                "word": response.word,
                "da_delta": response.mean_da_delta,
                "ne_delta": response.mean_ne_delta,
                "cortisol_delta": response.mean_cortisol_delta,
            }
            for response in result.colony_responses
        ]
        st.dataframe(nm_rows, use_container_width=True)

    st.caption(
        f"{DISCLAIMER} Validation correlation with Warriner et al. (2013): "
        f"Spearman rho = {result.spearman_rho_valence:.3f} "
        f"(n={result.n_words}, encoder={result.encoder_mode})."
    )


if __name__ == "__main__":
    main()
